BEGIN;
SET LOCAL search_path=pg_catalog,naijue_erp,pg_temp;
DO $historical_sales_hall$
DECLARE
 specs jsonb:=$hall_source_changes$[{"signature":"naijue_erp.guard_unified_document()","predecessor_sha256":"fa51aa3c79074a829c685127f6638152e26def788d919c19eb38bfffcb50f961","successor_sha256":"92b49eac416f4e156c57d4f56198fe3ac8ce47bd347d23ca0d36e6a7dbcc5bc8","replacements":[{"before":" RETURN NEW;\n","after":" IF TG_TABLE_NAME='sales_header' THEN\n  -- A label is not provenance. Only an exact protected source operation can\n  -- preserve unknown or cross-hall history; other paths use current same-hall facts.\n  DECLARE retained_hall boolean:=false; source_record uuid; source_proof jsonb;\n   source_audit jsonb; original_header jsonb; original_receipt jsonb; original_audit jsonb;\n  BEGIN\n   IF NEW.stock_basis='CUTOFF_HISTORY' AND NEW.import_batch_id IS NOT NULL\n    AND (TG_OP='INSERT' OR (TG_OP='UPDATE'\n     AND NEW.hall_id IS NOT DISTINCT FROM OLD.hall_id\n     AND NEW.warehouse_id IS NOT DISTINCT FROM OLD.warehouse_id)) THEN\n    SELECT s.id INTO source_record FROM naijue_erp.import_record s\n     JOIN naijue_erp.import_batch b ON b.id=s.import_batch_id\n     WHERE s.import_batch_id=NEW.import_batch_id AND s.target_type='SALES_HEADER'\n      AND s.source_entity_type='SALES_HEADER' AND s.target_id=NEW.id AND s.status='IMPORTED'\n      AND s.reviewed_at IS NOT NULL AND s.source_system=b.source_name\n      AND s.decision_reason LIKE '{%\"STANDARD_IMPORT_POINTER_V1\"%'\n      AND b.inventory_mode='DOCUMENT_CONVERSION' AND b.mapping_version='DOCUMENT_CONVERSION_V1'\n      AND ((TG_OP='INSERT' AND b.status IN ('STAGED','VALIDATING')) OR (TG_OP='UPDATE' AND b.status='IMPORTED'));\n    IF source_record IS NOT NULL THEN\n     source_proof:=naijue_erp.standard_import_record_proof(source_record);\n     SELECT a.after_values INTO STRICT source_audit FROM naijue_erp.audit_change a\n      WHERE a.operation_id=(source_proof->>'operation_id')::uuid;\n     -- Reuse the existing explicit historical source profile, never a caller flag.\n     IF source_proof->'fields'->>'stock_basis'='CUTOFF_HISTORY'\n      AND source_proof->'fields'->>'import_batch_id'=NEW.import_batch_id::text\n      AND source_proof->'fields'->'hall_id' IS NOT DISTINCT FROM n->'hall_id'\n      AND source_proof->'fields'->'warehouse_id' IS NOT DISTINCT FROM n->'warehouse_id'\n      AND source_proof->'fields' ?& ARRAY['hall_id','warehouse_id']\n      AND source_proof->'historical_hall_evidence'->>'format_version' IN ('HISTORICAL_SALES_HALL_EVIDENCE_V1','HISTORICAL_SALES_HALL_EVIDENCE_V2')\n      AND source_proof->'historical_hall_evidence'->'selected_hall_id' IS NOT DISTINCT FROM n->'hall_id'\n      AND source_proof->'historical_hall_evidence'->'warehouse_id' IS NOT DISTINCT FROM n->'warehouse_id'\n      AND jsonb_typeof(source_proof->'source_refs')='array' AND jsonb_array_length(source_proof->'source_refs')>0\n      AND EXISTS(SELECT 1 FROM naijue_erp.audit_change init_a JOIN naijue_erp.operation_receipt init_r ON init_r.id=init_a.operation_id\n       WHERE init_r.id=(source_audit->'whole_package_v2'->>'root_operation')::uuid\n        AND init_r.action='IMPORT_INITIALIZE_CURRENT_ADMIN' AND init_r.status='COMMITTED'\n        AND init_a.object_type='IMPORT' AND init_a.object_id=init_r.target_id\n        AND init_a.action=init_r.action AND init_a.actor_account_id=init_r.actor_account_id\n        AND init_a.after_values->'request'->'payload'->>'document_batch_id'=NEW.import_batch_id::text\n        AND init_a.after_values->'request'->'payload'->>'schema_declarations_sha256' IN ('f5d4e26d8cfae8cc96d42a43b01c6c49217a9927d1b0dc42af0c1b4c3ce29b66','b460db7ded610e6afe0fc8d506fedb8eda9d947819571211a25ecc5b52a39c0b')) THEN\n      IF TG_OP='INSERT' THEN\n       retained_hall:=naijue_erp.standard_import_row_intent('SALES_HEADER',n) IS TRUE\n        AND source_proof->'current_operation'='true'::jsonb\n        AND to_jsonb(jsonb_populate_record(NULL::naijue_erp.sales_header,source_proof->'fields'))=n;\n      ELSE\n       SELECT to_jsonb(r),to_jsonb(a) INTO STRICT original_receipt,original_audit\n        FROM naijue_erp.operation_receipt r JOIN naijue_erp.audit_change a ON a.operation_id=r.id\n        WHERE r.target_type='SALES' AND r.target_id=OLD.id AND r.action='MIGRATE_DOCUMENT';\n       original_header:=original_audit->'after_values'->'header';\n       retained_hall:=OLD.stock_basis='CUTOFF_HISTORY' AND OLD.import_batch_id=NEW.import_batch_id\n        AND original_receipt->>'status'='COMMITTED'\n        AND original_audit->>'object_type'='SALES' AND original_audit->>'object_id'=OLD.id::text\n        AND original_audit->>'action'='MIGRATE_DOCUMENT'\n        AND original_audit->'actor_account_id'=original_receipt->'actor_account_id'\n        AND original_audit->'old_version'='null'::jsonb AND original_audit->'before_values'='null'::jsonb\n        AND original_audit->'occurred_at'=original_receipt->'completed_at'\n        AND original_audit->'after_values'->>'sourceRecordId'=source_record::text\n        AND original_receipt->'result_data'->>'sourceRecordId'=source_record::text\n        AND original_receipt->'result_data'->>'exposureDigest'=encode(sha256(convert_to(\n         (original_audit->'after_values'-ARRAY['baseline','sourceRecordId'])::text,'UTF8')),'hex')\n        AND to_jsonb(jsonb_populate_record(NULL::naijue_erp.sales_header,source_proof->'fields'))\n         =to_jsonb(jsonb_populate_record(NULL::naijue_erp.sales_header,original_header))\n        AND original_header->'hall_id' IS NOT DISTINCT FROM o->'hall_id'\n        AND original_header->'warehouse_id' IS NOT DISTINCT FROM o->'warehouse_id';\n      END IF;\n     END IF;\n    END IF;\n   END IF;\n   IF retained_hall IS NOT TRUE THEN\n    IF NEW.hall_id IS NULL OR NOT EXISTS(SELECT 1 FROM naijue_erp.hall WHERE id=NEW.hall_id AND enabled) THEN\n     RAISE EXCEPTION 'SALES_CURRENT_HALL_REQUIRED' USING ERRCODE='23514'; END IF;\n    IF NOT EXISTS(SELECT 1 FROM naijue_erp.warehouse WHERE id=NEW.warehouse_id AND enabled AND hall_id=NEW.hall_id) THEN\n     RAISE EXCEPTION 'SALES_CURRENT_WAREHOUSE_HALL_MISMATCH' USING ERRCODE='23514'; END IF;\n   END IF;\n  END;\n END IF;\n RETURN NEW;\n"}],"security_definer":false,"returns":"trigger"},{"signature":"naijue_erp.standard_whole_package_command_v2(jsonb,text,text,uuid,integer)","predecessor_sha256":"8d66fc0b618be87284dd60d00d2fae656458bf7b8adda7fb7405d0a475bcb93d","successor_sha256":"33fada56b538c2e86ec1ad05208ba8fa568c0652d3ef41be83565bdaa7f0d0c6","replacements":[{"before":"  IF payload ? 'schema_declarations_sha256' AND (jsonb_typeof(payload->'schema_declarations_sha256') IS DISTINCT FROM 'string' OR payload->>'schema_declarations_sha256' NOT IN ('e929e89fe7f026d10e6fd35af37d1eb48cd07db2f7da4eed76352e497b134cb9','7b8b084f726078b65a98b92fdddce504a985d3eaa08adb69938035991ebbe274','9e035b8da32e92d40a55696dfaf256f0a1865350656a011ae7a4abda0548ce5a','89117aebb5064a3f42065aaab077ffd0e90ec0fee07898e5416ee3c1ff18130e')) THEN","after":"  IF payload ? 'schema_declarations_sha256' AND (jsonb_typeof(payload->'schema_declarations_sha256') IS DISTINCT FROM 'string' OR payload->>'schema_declarations_sha256' NOT IN ('e929e89fe7f026d10e6fd35af37d1eb48cd07db2f7da4eed76352e497b134cb9','7b8b084f726078b65a98b92fdddce504a985d3eaa08adb69938035991ebbe274','9e035b8da32e92d40a55696dfaf256f0a1865350656a011ae7a4abda0548ce5a','89117aebb5064a3f42065aaab077ffd0e90ec0fee07898e5416ee3c1ff18130e','f5d4e26d8cfae8cc96d42a43b01c6c49217a9927d1b0dc42af0c1b4c3ce29b66','b460db7ded610e6afe0fc8d506fedb8eda9d947819571211a25ecc5b52a39c0b')) THEN"},{"before":"       ('7b8b084f726078b65a98b92fdddce504a985d3eaa08adb69938035991ebbe274','9e035b8da32e92d40a55696dfaf256f0a1865350656a011ae7a4abda0548ce5a','89117aebb5064a3f42065aaab077ffd0e90ec0fee07898e5416ee3c1ff18130e')","after":"       ('7b8b084f726078b65a98b92fdddce504a985d3eaa08adb69938035991ebbe274','9e035b8da32e92d40a55696dfaf256f0a1865350656a011ae7a4abda0548ce5a','89117aebb5064a3f42065aaab077ffd0e90ec0fee07898e5416ee3c1ff18130e','f5d4e26d8cfae8cc96d42a43b01c6c49217a9927d1b0dc42af0c1b4c3ce29b66','b460d