et_hall_id'=hall_evidence->'selected_hall_id') THEN RAISE EXCEPTION 'HISTORICAL_HALL_RESOLUTION_REQUIRED' USING ERRCODE='23514'; END IF;\n END IF;\n ELSE\n\n IF jsonb_typeof(hall_evidence) IS DISTINCT FROM 'object'\n  OR hall_evidence-ARRAY['format_version','basis','original_hall_id','selected_hall_id','warehouse_id','warehouse_hall_id_at_capture','warehouse_version','captured_at','has_difference','review_required']<>'{}'\n  OR NOT(hall_evidence ?& ARRAY['format_version','basis','original_hall_id','selected_hall_id','warehouse_id','warehouse_hall_id_at_capture','warehouse_version','captured_at','has_difference','review_required'])\n  OR hall_evidence->>'format_version' IS DISTINCT FROM 'HISTORICAL_SALES_HALL_EVIDENCE_V1'\n  OR coalesce(hall_evidence->>'basis','') NOT IN ('ORIGINAL','MIGRATION_DERIVED','PENDING_REVIEW')\n  OR (hall_evidence->>'warehouse_id' ~ '^[a-f0-9]{8}(-[a-f0-9]{4}){3}-[a-f0-9]{12}$') IS DISTINCT FROM true\n  OR jsonb_typeof(hall_evidence->'has_difference') IS DISTINCT FROM 'boolean' OR jsonb_typeof(hall_evidence->'review_required') IS DISTINCT FROM 'boolean'\n  OR EXISTS(SELECT 1 FROM unnest(ARRAY['original_hall_id','selected_hall_id','warehouse_hall_id_at_capture']) field\n   WHERE hall_evidence->field IS DISTINCT FROM 'null'::jsonb AND (jsonb_typeof(hall_evidence->field) IS DISTINCT FROM 'string'\n    OR (hall_evidence->>field ~ '^[a-f0-9]{8}(-[a-f0-9]{4}){3}-[a-f0-9]{12}$') IS DISTINCT FROM true)) THEN\n  RAISE EXCEPTION 'HISTORICAL_HALL_EVIDENCE_SHAPE' USING ERRCODE='23514'; END IF;\n IF (hall_evidence->'warehouse_version'='null'::jsonb) IS DISTINCT FROM (hall_evidence->'captured_at'='null'::jsonb)\n  OR (hall_evidence->'warehouse_hall_id_at_capture'<>'null'::jsonb AND hall_evidence->'warehouse_version'='null'::jsonb) THEN\n  RAISE EXCEPTION 'HISTORICAL_HALL_CAPTURE_REQUIRED' USING ERRCODE='23514'; END IF;\n IF hall_evidence->'warehouse_version'<>'null'::jsonb THEN\n  IF jsonb_typeof(hall_evidence->'warehouse_version') IS DISTINCT FROM 'number'\n   OR (hall_evidence->>'warehouse_version' ~ '^[1-9][0-9]{0,9}$') IS DISTINCT FROM true\n   OR (hall_evidence->>'warehouse_version')::numeric>2147483647\n   OR jsonb_typeof(hall_evidence->'captured_at') IS DISTINCT FROM 'string'\n   OR (hall_evidence->>'captured_at' ~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}T[0-9]{2}:[0-9]{2}:[0-9]{2}([.][0-9]{1,9})?(Z|[+-][0-9]{2}:[0-9]{2})$') IS DISTINCT FROM true\n   OR NOT isfinite((hall_evidence->>'captured_at')::timestamptz) THEN\n   RAISE EXCEPTION 'HISTORICAL_HALL_CAPTURE_REQUIRED' USING ERRCODE='23514'; END IF;\n END IF;\n IF (hall_evidence->>'basis'='ORIGINAL' AND (hall_evidence->'original_hall_id'='null'::jsonb\n    OR hall_evidence->'selected_hall_id' IS DISTINCT FROM hall_evidence->'original_hall_id'\n    OR (hall_evidence->>'has_difference')::boolean IS DISTINCT FROM (hall_evidence->'warehouse_hall_id_at_capture'<>'null'::jsonb AND hall_evidence->'warehouse_hall_id_at_capture'<>hall_evidence->'original_hall_id')\n    OR (hall_evidence->>'review_required')::boolean IS DISTINCT FROM ((hall_evidence->>'has_difference')::boolean OR hall_evidence->'warehouse_hall_id_at_capture'='null'::jsonb)))\n  OR (hall_evidence->>'basis'='MIGRATION_DERIVED' AND (hall_evidence->'original_hall_id'<>'null'::jsonb OR hall_evidence->'warehouse_hall_id_at_capture'='null'::jsonb\n    OR hall_evidence->'selected_hall_id' IS DISTINCT FROM hall_evidence->'warehouse_hall_id_at_capture' OR hall_evidence->'has_difference'<>'false'::jsonb OR hall_evidence->'review_required'<>'false'::jsonb))\n  OR (hall_evidence->>'basis'='PENDING_REVIEW' AND (hall_evidence->'original_hall_id'<>'null'::jsonb OR hall_evidence->'selected_hall_id'<>'null'::jsonb\n    OR hall_evidence->'warehouse_hall_id_at_capture'<>'null'::jsonb OR hall_evidence->'has_difference'<>'false'::jsonb OR hall_evidence->'review_required'<>'true'::jsonb)) THEN\n  RAISE EXCEPTION 'HISTORICAL_HALL_EVIDENCE_CONTRADICTION' USING ERRCODE='23514'; END IF;\n END IF;\n\n     IF hall_approved IS NULL OR hall_approved->>'source_key' IS DISTINCT FROM source_key\n      OR NOT((hall_approved->'source_refs') @> (entry->'source_refs') AND (entry->'source_refs') @> (hall_approved->'source_refs'))\n      OR jsonb_array_length(hall_approved->'source_refs')<>jsonb_array_length(entry->'source_refs')\n      OR (SELECT count(DISTINCT ref) FROM jsonb_array_elements(entry->'source_refs') ref)<>jsonb_array_length(entry->'source_refs')\n      OR hall_approved->'evidence' IS DISTINCT FROM hall_evidence\n      OR fields->'hall_id' IS DISTINCT FROM hall_evidence->'selected_hall_id' OR fields->'warehouse_id' IS DISTINCT FROM hall_evidence->'warehouse_id' THEN\n      RAISE EXCEPTION 'HISTORICAL_HALL_APPROVAL_MEMBERSHIP' USING ERRCODE='23514'; END IF;\n     IF hall_evidence->>'format_version'='HISTORICAL_SALES_HALL_EVIDENCE_V2' THEN\n      -- Lock and compare the actual new target row in this same transaction.\n      PERFORM 1 FROM naijue_erp.warehouse w WHERE w.id=(hall_target->>'warehouse_id')::uuid\n       AND w.hall_id=(hall_target->>'hall_id')::uuid AND w.version=(hall_target->>'version')::integer\n       AND w.version>0 FOR SHARE;\n      IF NOT FOUND THEN RAISE EXCEPTION 'HISTORICAL_HALL_CAPTURE_CHANGED' USING ERRCODE='23514'; END IF;\n     ELSE\n     IF hall_evidence->'warehouse_version'<>'null'::jsonb AND NOT EXISTS(SELECT 1 FROM naijue_erp.warehouse w\n      WHERE w.id=(hall_evidence->>'warehouse_id')::uuid AND w.version=(hall_evidence->>'warehouse_version')::integer\n       AND to_jsonb(w.hall_id) IS NOT DISTINCT FROM hall_evidence->'warehouse_hall_id_at_capture') THEN\n      RAISE EXCEPTION 'HISTORICAL_HALL_CAPTURE_CHANGED' USING ERRCODE='23514'; END IF;\n     END IF;\n    END IF;\n    IF entry ? 'zero_amount_archive' THEN\n"},{"before":"    source_hash:=encode(sha256(convert_to(parsed::text,'UTF8')),'hex');","after":"    IF entry ? 'historical_hall_evidence' THEN parsed:=parsed||jsonb_build_object('historical_hall_evidence',entry->'historical_hall_evidence'); END IF;\n    source_hash:=encode(sha256(convert_to(parsed::text,'UTF8')),'hex');"},{"before":"    IF entry ? 'zero_amount_archive' THEN item:=item||jsonb_build_object('zero_amount_archive',entry->'zero_amount_archive'); END IF;","after":"    IF entry ? 'historical_hall_evidence' THEN item:=item||jsonb_build_object('historical_hall_evidence',entry->'historical_hall_evidence'); END IF;\n    IF entry ? 'zero_amount_archive' THEN item:=item||jsonb_build_object('zero_amount_archive',entry->'zero_amount_archive'); END IF;"}],"security_definer":true,"returns":"jsonb"}]$hall_source_changes$::jsonb;
 dependencies jsonb:=$hall_dependencies$[{"signature":"naijue_erp.assert_unified_current_actor(pg_catalog.uuid,pg_catalog.timestamptz,pg_catalog.text,pg_catalog.uuid,pg_catalog.text)","sha256":"0a7fd1974200a8145e0e57a351c4f46f85a02636541eccde436196fccadc4731"},{"signature":"naijue_erp.standard_import_record_proof(pg_catalog.uuid)","sha256":"60a84418cef1b166555c9a56a5503397eea04b4c753122de00c4a254d7d5c241"},{"signature":"naijue_erp.standard_import_row_intent(text,jsonb)","sha256":"4ea68e6eee19a05be7ad9aaa7eefcfb33bbf9af2d41a790c808e3b2693aef3ed"},{"signature":"naijue_erp.standard_whole_package_context_v2(uuid)","sha256":"ef1631ee8ac06527c13253aad1eec7d8902dd6411d46b1db729fdbf589b2b4e2"}]$hall_dependencies$::jsonb;
 spec jsonb; dep jsonb; change jsonb; routine oid; before_body text; after_body text; definition text;
 before_meta jsonb; after_meta jsonb; table_id regclass; hall_number smallint;
 before_columns jsonb; after_columns jsonb; before_constraints jsonb; after_constraints jsonb;
 before_triggers jsonb; after_triggers jsonb; before_indexes jsonb; after_indexes jsonb;
 before_relation jsonb; after_relation jsonb;
BEGIN
 IF (SELECT array_agg(c.relname::text ORDER BY c.relname) FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace
   WHERE n.nspname='naijue_erp' AND c.relkind IN ('r','p')) IS DISTINCT FROM ARRAY['audit_change','auth_session','barcode_scheme','color','customer','fit','hall','import_batch','import_record','inventory_balance','inventory_ledger','operation_receipt','payment_account','payment_account_hall','payment_method','product','product_category','product_image','runtime_document_number_allocation','sales_header','sales_line','sales_settlement','schema_migration','season','size','size_group','size_group_member','sku','sku_barcode','staff','supplier','transfer_header','transfer_line','user_account','warehouse']::text[]
  OR (SELECT count(*) FROM pg_proc WHERE pronamespace='naijue_erp'::regnamespace AND prokind IN ('f','p'))<>152 THEN
  RAISE EXCEPTION 'SALES_HALL_EXACT35_PREDECESSOR_REQUIRED' USING ERRCODE='55000'; END IF;
 LOCK TABLE naijue_erp.sales_header IN ACCESS EXCLUSIVE MODE;
 FOR dep IN SELECT value FROM jsonb_array_elements(dependencies) LOOP
  IF (SELECT encode(sha256(convert_to(prosrc,'UTF8')),'hex') FROM pg_proc WHERE oid=to_regprocedure(dep->>'signature')) IS DISTINCT FROM dep->>'sha256' THEN
   RAISE EXCEPTION 'SALES_HALL_DEPENDENCY_DIFFERS: %',dep->>'signature' USING ERRCODE='55000'; END IF;
 END LOOP;
 FOR spec IN SELECT value FROM jsonb_array_elements(specs) LOOP
  routine:=to_regprocedure(spec->>'signature');
  SELECT p.prosrc,to_jsonb(p)-'prosrc' INTO before_body,before_meta FROM pg_proc p WHERE p.oid=routine;
  IF before_body IS NULL OR encode(sha256(convert_to(before_body,'UTF8')),'hex') IS DISTINCT FROM spec->>'predecessor_sha256' THEN
   RAISE EXCEPTION 'SALES_HALL_PREDECESSOR_DIFFERS' USING ERRCODE='55000'; END IF;
  IF before_meta->'prosecdef' IS DISTINCT FROM spec->'security_definer' OR before_meta->>'prorettype' IS DISTINCT FROM (spec->>'returns')::regtype::oid::text
    OR before_meta->>'proowner' IS DISTINCT FROM (SELECT nspowner::text FROM pg_namespace WHERE nspname='naijue_erp')
    OR (before_meta->'proconfig' @> '["search_path=pg_catalog, naijue_erp, pg_temp"]'::jsonb) IS DISTINCT FROM true THEN
   RAISE EXCEPTION 'SALES_HALL_METADATA_UNSAFE' USING ERRCODE='55000'; END IF;
  definition:=pg_get_functiondef(routine);after_body:=before_body;
  FOR change IN SELECT value FROM jsonb_array_elements(spec->'replacements') LOOP
   IF coalesce(length(change->>'before'),0)=0
    OR (length(after_body)-length(replace(after_body,change->>'before','')))/length(change->>'before')<>1
    OR (length(definition)-length(replace(definition,change->>'before','')))/length(change->>'before')<>1 THEN
    RAISE EXCEPTION 'SALES_HALL_ANCHOR_DIFFERS' USING ERRCODE='55000'; END IF;
   after_body:=replace(after_body,change->>'before',change->>'after');
   definition:=replace(definition,change->>'before',change->>'after');
  END LOOP;
  IF encode(sha256(convert_to(after_body,'UTF8')),'hex') IS DISTINCT FROM spec->>'successor_sha256' THEN
   RAISE EXCEPTION 'SALES_HALL_OUTPUT_DIFFERS' USING ERRCODE='55000'; END IF;
  EXECUTE definition;
  SELECT p.prosrc,to_jsonb(p)-'prosrc' INTO after_body,after_meta FROM pg_proc p WHERE p.oid=routine;
  IF before_meta IS DISTINCT FROM after_meta OR encode(sha256(convert_to(after_body,'UTF8')),'hex') IS DISTINCT FROM spec->>'successor_sha256' THEN
   RAISE EXCEPTION 'SALES_HALL_POSTCONDITION_FAILED' USING ERRCODE='55000'; END IF;
 END LOOP;
 FOREACH table_id IN ARRAY ARRAY['naijue_erp.sales_header'::regclass] LOOP
  SELECT attnum INTO STRICT hall_number FROM pg_attribute WHERE attrelid=table_id AND attname='hall_id'
   AND atttypid='uuid'::regtype AND attnotnull AND NOT attisdropped AND NOT atthasdef AND attgenerated='';
  IF NOT EXISTS(SELECT 1 FROM pg_constraint c WHERE c.conrelid=table_id AND c.contype='f' AND c.conkey=ARRAY[hall_number]
    AND c.confrelid='naijue_erp.hall'::regclass AND c.convalidated) THEN
   RAISE EXCEPTION 'SALES_HALL_FOREIGN_KEY_REQUIRED' USING ERRCODE='55000'; END IF;
  SELECT jsonb_agg(CASE WHEN a.attnum=hall_number THEN to_jsonb(a)-'attnotnull' ELSE to_jsonb(a) END ORDER BY a.attnum) INTO before_columns FROM pg_attribute a WHERE a.attrelid=table_id;
  SELECT coalesce(jsonb_agg(to_jsonb(c) ORDER BY c.oid),'[]') INTO before_constraints FROM pg_constraint c WHERE c.conrelid=table_id AND NOT(c.contype='n' AND c.conkey=ARRAY[hall_number]);
  SELECT coalesce(jsonb_agg(to_jsonb(t) ORDER BY t.oid),'[]') INTO before_triggers FROM pg_trigger t WHERE t.tgrelid=table_id;
  SELECT coalesce(jsonb_agg(to_jsonb(i) ORDER BY i.indexrelid),'[]') INTO before_indexes FROM pg_index i WHERE i.indrelid=table_id;
  SELECT jsonb_build_object('owner',relowner,'acl',relacl,'rls',relrowsecurity,'forceRls',relforcerowsecurity) INTO before_relation FROM pg_class WHERE oid=table_id;
  EXECUTE format('ALTER TABLE %s ALTER COLUMN hall_id DROP NOT NULL',table_id);
  SELECT jsonb_agg(CASE WHEN a.attnum=hall_number THEN to_jsonb(a)-'attnotnull' ELSE to_jsonb(a) END ORDER BY a.attnum) INTO after_columns FROM pg_attribute a WHERE a.attrelid=table_id;
  SELECT coalesce(jsonb_agg(to_jsonb(c) ORDER BY c.oid),'[]') INTO after_constraints FROM pg_constraint c WHERE c.conrelid=table_id AND NOT(c.contype='n' AND c.conkey=ARRAY[hall_number]);
  SELECT coalesce(jsonb_agg(to_jsonb(t) ORDER BY t.oid),'[]') INTO after_triggers FROM pg_trigger t WHERE t.tgrelid=table_id;
  SELECT coalesce(jsonb_agg(to_jsonb(i) ORDER BY i.indexrelid),'[]') INTO after_indexes FROM pg_index i WHERE i.indrelid=table_id;
  SELECT jsonb_build_object('owner',relowner,'acl',relacl,'rls',relrowsecurity,'forceRls',relforcerowsecurity) INTO after_relation FROM pg_class WHERE oid=table_id;
  IF before_columns IS DISTINCT FROM after_columns OR before_constraints IS DISTINCT FROM after_constraints
   OR before_triggers IS DISTINCT FROM after_triggers OR before_indexes IS DISTINCT FROM after_indexes OR before_relation IS DISTINCT FROM after_relation
   OR NOT EXISTS(SELECT 1 FROM pg_attribute WHERE attrelid=table_id AND attnum=hall_number AND NOT attnotnull) THEN
   RAISE EXCEPTION 'SALES_HALL_SCHEMA_DELTA_DIFFERS' USING ERRCODE='55000'; END IF;
 END LOOP;
END $historical_sales_hall$;
COMMIT;
